import{_ as c,I as n,o as p,c as h,b6 as i,j as e,J as s,w as r,a as t}from"./chunks/framework.BUXTSoD9.js";const w=JSON.parse('{"title":"Custom Dify Agent Platform","description":"","frontmatter":{},"headers":[],"relativePath":"en/stage-2/assignments/custom-dify-agent-platform/index.md","filePath":"en/stage-2/assignments/custom-dify-agent-platform/index.md"}'),g={name:"en/stage-2/assignments/custom-dify-agent-platform/index.md"},u={style:{margin:"32px 0"}};function m(b,a,f,k,y,v){const l=n("StepBar"),o=n("ClientOnly"),d=n("el-card");return p(),h("div",null,[a[2]||(a[2]=i('<h1 id="custom-dify-agent-platform" tabindex="-1">Custom Dify Agent Platform <a class="header-anchor" href="#custom-dify-agent-platform" aria-label="Permalink to “Custom Dify Agent Platform”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>This project requires you to build an agent platform that replicates the core Dify experience, based on a real PRD. You&#39;ll build a user console, admin dashboard, and platform backend, implementing core features like agent management, conversations, logging, and knowledge base.</p><p>This is the comprehensive practical section of Stage 2. Unlike previous single-page or single-feature projects, this one requires building a &quot;platform-like&quot; AI product — with multiple roles, multiple modules, data persistence, and model call pipelines.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><p>Before starting this project, you should already be familiar with:</p><ul><li>Frontend page design and component libraries (<a href="./../../frontend/ui-design/">UI Design</a>, <a href="./../../frontend/modern-component-library/">Modern Component Libraries</a>)</li><li>Backend API design and development (<a href="./../../backend/ai-interface-code/">API Code</a>)</li><li>Database fundamentals and Supabase (<a href="./../../backend/database-supabase/">Database to Supabase</a>)</li><li>Git workflow and deployment (<a href="./../../backend/git-workflow/">Git &amp; GitHub</a>, <a href="./../../backend/zeabur-deployment/">Web App Deployment</a>)</li></ul><h2 id="learning-objectives" tabindex="-1">Learning Objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to “Learning Objectives”">​</a></h2><p>After completing this project, you will be able to:</p><ol><li>Read and understand a real PRD, extracting a development task list</li><li>Design the page architecture and data models for an agent platform</li><li>Implement the full pipeline for agent creation, conversation, and logging</li><li>Use AI assistance to build a platform-type product</li><li>Complete end-to-end integration and deliver a demo-ready AI platform prototype</li></ol><h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to “Project Overview”">​</a></h2><p>You will build a Dify-like agent platform with two subsystems:</p><table tabindex="0"><thead><tr><th>Subsystem</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>User Console</strong></td><td>Create agents, configure prompts, start conversations, view logs, manage knowledge base</td></tr><tr><td><strong>Admin Dashboard</strong></td><td>View user data, platform resource usage, API call statistics</td></tr></tbody></table><p>The backend needs to support: agent management, session management, message storage, model calls, call logging, and knowledge base integration.</p><div class="tip custom-block"><p class="custom-block-title">PRD</p><p>The requirements document for this project is on GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/en/stage-2/assignments/custom-dify-agent-platform/PRD.md" target="_blank" rel="noreferrer">View PRD</a></p></div>',15)),e("div",u,[s(o,null,{default:r(()=>[s(l,{active:0,items:[{title:"Requirements",description:"Read PRD, define pages, capability scope, auth, and data models"},{title:"Scaffold",description:"Use AI to generate user console and admin dashboard skeletons"},{title:"Iterate",description:"Add agents, conversations, logs, and knowledge base module by module"},{title:"Launch",description:"End-to-end testing, deploy, and prepare demo"}]})]),_:1})]),a[3]||(a[3]=i(`<h2 id="part-1-requirements-analysis" tabindex="-1">Part 1: Requirements Analysis <a class="header-anchor" href="#part-1-requirements-analysis" aria-label="Permalink to “Part 1: Requirements Analysis”">​</a></h2><h3 id="_1-1-read-the-prd" tabindex="-1">1.1 Read the PRD <a class="header-anchor" href="#_1-1-read-the-prd" aria-label="Permalink to “1.1 Read the PRD”">​</a></h3><p>Open the PRD document and answer these key questions:</p><ul><li>Which of agents, sessions, logs, and knowledge base should go into the MVP?</li><li>Is the page and route list finalized?</li><li>What are the boundaries of model calls and log recording?</li><li>Should multi-tenancy and complex workflows be deferred?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>If the above questions don&#39;t have clear answers, don&#39;t start coding. Unclear requirements are the most common cause of rework.</p></div><h3 id="_1-2-confirm-system-architecture" tabindex="-1">1.2 Confirm System Architecture <a class="header-anchor" href="#_1-2-confirm-system-architecture" aria-label="Permalink to “1.2 Confirm System Architecture”">​</a></h3><p>Map out the overall architecture based on the PRD:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; app[&quot;User Console&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;Admin Dashboard&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;Auth&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; agent[&quot;Agent Configuration&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; chat[&quot;Conversation&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; llm[&quot;Model Call&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; db[&quot;Database&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; kb[&quot;Knowledge Base&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; logs[&quot;Call Logs &amp; Platform Overview&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  logs --&gt; db</span></span></code></pre></div><h2 id="part-2-project-scaffolding" tabindex="-1">Part 2: Project Scaffolding <a class="header-anchor" href="#part-2-project-scaffolding" aria-label="Permalink to “Part 2: Project Scaffolding”">​</a></h2><h3 id="_2-1-generate-frontend-pages" tabindex="-1">2.1 Generate Frontend Pages <a class="header-anchor" href="#_2-1-generate-frontend-pages" aria-label="Permalink to “2.1 Generate Frontend Pages”">​</a></h3><p>Prompt reference:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Based on the current PRD, help me generate a frontend scaffold for a Dify-like agent platform.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requirements:</span></span>
<span class="line"><span>1. User side: login, agent list, agent configuration, conversation page, logs page, knowledge base page</span></span>
<span class="line"><span>2. Admin side: dashboard homepage, user overview, resource usage overview</span></span>
<span class="line"><span>3. Only generate page structure with mock data first, no real API integration</span></span>
<span class="line"><span>4. Style should look like a modern AI platform</span></span></code></pre></div><h3 id="_2-2-verify-page-structure" tabindex="-1">2.2 Verify Page Structure <a class="header-anchor" href="#_2-2-verify-page-structure" aria-label="Permalink to “2.2 Verify Page Structure”">​</a></h3><p>Check each item:</p><ul><li>[ ] User console and admin dashboard entry points are separate</li><li>[ ] Agent list, configuration, conversation, logs, and knowledge base pages are complete</li><li>[ ] Admin dashboard homepage and user overview pages are accessible</li><li>[ ] Mock data shows basic UI states</li></ul><h2 id="part-3-iterative-development" tabindex="-1">Part 3: Iterative Development <a class="header-anchor" href="#part-3-iterative-development" aria-label="Permalink to “Part 3: Iterative Development”">​</a></h2><h3 id="_3-1-module-by-module-progress" tabindex="-1">3.1 Module-by-Module Progress <a class="header-anchor" href="#_3-1-module-by-module-progress" aria-label="Permalink to “3.1 Module-by-Module Progress”">​</a></h3><p>On top of the scaffold, add features module by module in this order:</p><ol><li><strong>Authentication</strong>: Registration, login, role differentiation</li><li><strong>Agent Management</strong>: Create, edit, delete, prompt configuration</li><li><strong>Conversation</strong>: Session creation, message exchange, model calls</li><li><strong>Logging</strong>: Latency, token usage, error recording</li><li><strong>Knowledge Base</strong> (bonus): Document upload, retrieval, result injection</li><li><strong>Admin Dashboard</strong>: User data, resource usage, call statistics</li></ol><p>After each module, use this self-check table:</p><table tabindex="0"><thead><tr><th>Check Item</th><th>Verification Method</th></tr></thead><tbody><tr><td>Page consistency</td><td>Do page count and features match the PRD?</td></tr><tr><td>API completeness</td><td>Are agents, chat, logs, knowledge APIs complete?</td></tr><tr><td>Auth isolation</td><td>Can users only manage their own agents and sessions?</td></tr><tr><td>Data consistency</td><td>Do messages, logs, and documents data align?</td></tr><tr><td>Demo readiness</td><td>Can you demo &quot;create agent → chat → view logs&quot; end-to-end?</td></tr></tbody></table><h3 id="_3-2-knowledge-base-integration-bonus" tabindex="-1">3.2 Knowledge Base Integration (Bonus) <a class="header-anchor" href="#_3-2-knowledge-base-integration-bonus" aria-label="Permalink to “3.2 Knowledge Base Integration (Bonus)”">​</a></h3><p>If you want to add knowledge base capabilities, add a &quot;knowledge base toggle&quot; for each agent:</p><ul><li>When enabled: retrieve knowledge snippets first, then send them along with the user&#39;s question to the model</li><li>When disabled: respond in normal conversation mode</li></ul><p>For the first version, don&#39;t aim for complex RAG — just ensure &quot;retrieval results are visible and the call chain is explainable.&quot;</p><h2 id="part-4-integration-launch" tabindex="-1">Part 4: Integration &amp; Launch <a class="header-anchor" href="#part-4-integration-launch" aria-label="Permalink to “Part 4: Integration &amp; Launch”">​</a></h2><h3 id="_4-1-end-to-end-testing" tabindex="-1">4.1 End-to-End Testing <a class="header-anchor" href="#_4-1-end-to-end-testing" aria-label="Permalink to “4.1 End-to-End Testing”">​</a></h3><p>At minimum, verify these scenarios:</p><ul><li>Register → Create agent → Configure prompt → Start conversation → View logs</li><li>Admin login → View user data → View call statistics</li></ul><p>Pre-deployment checklist:</p><ul><li>[ ] All core APIs require login verification</li><li>[ ] Agent ownership permission checks pass</li><li>[ ] Conversation and log records are persisted to the database</li><li>[ ] Model API keys use environment variables, not hardcoded</li><li>[ ] Error messages are visible on the frontend, not just in the console</li></ul><h3 id="_4-2-deployment" tabindex="-1">4.2 Deployment <a class="header-anchor" href="#_4-2-deployment" aria-label="Permalink to “4.2 Deployment”">​</a></h3><p>Deploy the project to a public environment. For deployment instructions, see: <a href="./../../backend/git-workflow/">Git &amp; GitHub Workflow</a>, <a href="./../../backend/zeabur-deployment/">Web App Deployment</a>.</p><h2 id="deliverables" tabindex="-1">Deliverables <a class="header-anchor" href="#deliverables" aria-label="Permalink to “Deliverables”">​</a></h2><p>After completing this project, submit the following:</p><ul><li>[ ] Accessible live demo link</li><li>[ ] Source code repository link (with README)</li><li>[ ] PRD document</li><li>[ ] Core page screenshots (agent management, conversation, logs, admin dashboard)</li><li>[ ] 60-second demo video (covering create agent → chat → view logs)</li></ul><p>README should include at minimum: project overview, architecture description, tech stack, local setup steps, environment variable list, and API documentation.</p><h2 id="grading-criteria" tabindex="-1">Grading Criteria <a class="header-anchor" href="#grading-criteria" aria-label="Permalink to “Grading Criteria”">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Basic Requirements</th><th>Advanced Requirements</th></tr></thead><tbody><tr><td>Platform Completeness</td><td>agents / chat / logs pages are functional</td><td>Has clear navigation and unified design language</td></tr><tr><td>Business Loop</td><td>Can create agents and have real conversations</td><td>Supports multi-agent switching and session history</td></tr><tr><td>Data &amp; Tracking</td><td>Messages and call logs are queryable</td><td>Has token / latency statistics dashboard</td></tr><tr><td>Auth &amp; Security</td><td>Only logged-in users can access core APIs</td><td>Resource ownership verification is robust</td></tr><tr><td>Engineering Delivery</td><td>Deployable, demoable, clear README</td><td>Knowledge base integrated with explainable retrieval</td></tr></tbody></table><h2 id="pre-submission-checklist" tabindex="-1">Pre-Submission Checklist <a class="header-anchor" href="#pre-submission-checklist" aria-label="Permalink to “Pre-Submission Checklist”">​</a></h2>`,40)),s(d,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:r(()=>[...a[0]||(a[0]=[e("div",{style:{"font-weight":"bold","font-size":"16px"}},"Final check before submission",-1)])]),default:r(()=>[a[1]||(a[1]=e("ul",{style:{"list-style-type":"none","padding-left":"0"}},[e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),t(" Agent management, conversation, and logs pages accessible after login")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),t(" At least 1 agent can be created and successfully conversed with")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),t(" Each Q&A round can be found in the database")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),t(" Call failures show error messages on the frontend and are logged")])]),e("li",null,[e("label",null,[e("input",{type:"checkbox",disabled:""}),t(" Project is deployed, README and demo video are complete")])])],-1))]),_:1}),a[4]||(a[4]=i('<h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI Design</a></li><li><a href="./../../frontend/modern-component-library/">Modern Component Libraries</a></li><li><a href="./../../backend/database-supabase/">Database to Supabase</a></li><li><a href="./../../backend/ai-interface-code/">API Code with LLM Assistance</a></li><li><a href="./../../backend/git-workflow/">Git &amp; GitHub Workflow</a></li><li><a href="./../../backend/zeabur-deployment/">Web App Deployment</a></li></ul>',2))])}const A=c(g,[["render",m]]);export{w as __pageData,A as default};
